import { mkdtemp, mkdir, writeFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import { join } from 'node:path';
import { isDeepStrictEqual } from 'node:util';

const root = await mkdtemp('/home/genie/.local/share/mikro-engine-split/experiments-g8/native-header-proof-');
const cwd = join(root, 'cwd');
await mkdir(cwd, { mode: 0o700 });
const env = { HOME: join(root, 'home'), DSH_HOME: join(root, 'dsh'), GENIE_HOME: join(root, 'genie'), TMPDIR: root, PATH: '/home/genie/.hermes/node/bin:/usr/local/bin:/usr/bin:/bin', DSH_TELEMETRY_DISABLED: '1', NO_COLOR: '1' };
for (const value of [env.HOME, env.DSH_HOME, env.GENIE_HOME]) await mkdir(value, { mode: 0o700 });
for (const key of Object.keys(process.env)) delete process.env[key];
Object.assign(process.env, env);
process.chdir(cwd);
const require = createRequire('/home/genie/.dsh/runtime/0.2.0-rc.1/node_modules/@deepseek-ai/dsh/package.json');
const load = specifier => import(pathToFileURL(require.resolve(specifier)).href);
const { initializeProfileFromDefault, runProfile } = await load('@deepseek-ai/dsh/profile-boot');
const { createLaunchEnvironmentSnapshot } = await load('@deepseek-ai/dsh-launch-environment');
const { installModelSelection } = await load('@deepseek-ai/dsh-agent');
const { deriveTurnTokenUsage } = await load('@deepseek-ai/dsh-token-meter/client');
const { sessionFormatCatalog } = await load('@deepseek-ai/dsh-session-format-catalog');
const { reconcileSessions } = await import('file:///home/genie/orca/workspaces/genie/mikro-engine-split/.genie/wishes/mikro-engine-split/experiments/native-session-accounting.mjs');
const profile = 'header-proof';
initializeProfileFromDefault(profile, 'headless', env.DSH_HOME);
const patch = [
  { id: 'headless-runner', disabled: true },
  { id: 'headless-startup', disabled: true },
  { id: 'session-title-llm', disabled: true },
  { id: 'agent-default-model', config: { provider: 'deepseek-official', model: 'deepseek-flash' } },
  { id: 'tools', config: { mode: 'native' } },
  { id: 'session-persistence-jsonl', config: { root: join(root, 'sessions'), compression: 'none' } },
  { id: 'credentials', config: { path: join(env.DSH_HOME, '.credentials.yaml'), dshHome: env.DSH_HOME, watch: false } },
  { id: 'llm-deepseek', config: { apiKeyEnv: 'DEEPSEEK_API_KEY' } },
];
const patchPath = join(root, 'proof.patch.yml');
await writeFile(patchPath, JSON.stringify(patch), { mode: 0o600, flag: 'wx' });
let boot;
let handle;
let explicitHandle;
let inheritedHandle;
let requestCount = 0;
const proof = { schemaVersion: 1, kind: 'native-root-header-non-inference-proof', root, runtime: '0.2.0-rc.1', nativeWorkflowLaunched: false, credentialsProvided: false, originalObservationRecovered: false, profileScope: 'isolated public headless SDK; no experiment workflow loader or workflows installed', originalCauseStatus: 'inference: original live header was not retained' };
function projection(header) { return { ...header, delegationDepth: header.delegationDepth ?? 0 }; }
function compareFixture(live, durable) { return isDeepStrictEqual(live, durable); }
async function capture(sessionId) {
  const observation = await boot.ctx.sessionQuery.observeSession(sessionId, { projectionMode: 'none' });
  let durable;
  try {
    durable = await boot.ctx.sessionPersistence.open(sessionId, 'read');
    const read = await durable.read();
    const projected = projection(observation.header);
    const wire = sessionFormatCatalog.encodeCurrentHeader(projected, durable.inheritedEventCount);
    const decoded = sessionFormatCatalog.readHeader(wire);
    return { sessionId, source: observation.source, liveHeader: observation.header, durableHeader: durable.header, inheritedEventCount: durable.inheritedEventCount, observedInheritedEventCount: observation.inheritedEventCount, eventCount: read.events.length, rawHeaderEqual: isDeepStrictEqual(observation.header, durable.header), exactSdkDefaultProjectionEqual: isDeepStrictEqual(projected, durable.header), projection: projected, sdkWireHeader: wire, sdkReadHeader: decoded };
  } finally { observation[Symbol.dispose](); await durable?.close(); }
}
try {
  boot = await runProfile({ environment: createLaunchEnvironmentSnapshot([{ source: 'process', values: env }]), profile, patchFiles: [patchPath], args: [] });
  boot.ctx.on('agent/request', () => { requestCount++; throw new Error('no-inference header proof forbids all model requests'); });
  const sessionId = randomUUID();
  handle = await boot.ctx.agents.create({ sessionId, meta: { cwd }, agentOptions: { provider: 'deepseek-official', model: 'deepseek-flash' }, signal: new AbortController().signal, setup(agentCtx) { installModelSelection(agentCtx, { current: { provider: 'deepseek-official', model: 'deepseek-flash' }, assembled: undefined }); } });
  await handle.agent.whenIdle();
  const originalReconciliation = await reconcileSessions(boot.ctx, [sessionId], deriveTurnTokenUsage);
  proof.rootCapture = await capture(sessionId);
  proof.originalHelper = originalReconciliation;
  const explicitId = randomUUID();
  explicitHandle = await boot.ctx.agents.create({ sessionId: explicitId, meta: { cwd, delegationDepth: 0 }, agentOptions: { provider: 'deepseek-official', model: 'deepseek-flash' }, signal: new AbortController().signal, setup(agentCtx) { installModelSelection(agentCtx, { current: { provider: 'deepseek-official', model: 'deepseek-flash' }, assembled: undefined }); } });
  await explicitHandle.agent.whenIdle();
  proof.explicitRootHelper = await reconcileSessions(boot.ctx, [explicitId], deriveTurnTokenUsage);
  proof.explicitRootCapture = await capture(explicitId);
  proof.previousAttemptProofPaths = ['/home/genie/.local/share/mikro-engine-split/experiments-g8/native-header-proof-aHbspb/proof.json', '/home/genie/.local/share/mikro-engine-split/experiments-g8/native-header-proof-KxrU6f/proof.json', '/home/genie/.local/share/mikro-engine-split/experiments-g8/native-header-proof-VenC1i/proof.json'];
  const inherited = boot.ctx.sessions.fork(explicitId, undefined, randomUUID());
  proof.rawSessionStoreForkHeader = inherited.header;
  const inheritedAgentId = randomUUID();
  inheritedHandle = await boot.ctx.agents.create({ sessionId: inheritedAgentId, parentAgent: explicitHandle.agent, meta: { cwd, parentSession: explicitId, isSeeded: true, origin: 'subagent', delegationDepth: 1 }, seed: inherited.snapshotEvents(), inheritedEventCount: inherited.inheritedEventCount, agentOptions: { provider: 'deepseek-official', model: 'deepseek-flash' }, signal: new AbortController().signal, setup(agentCtx) { installModelSelection(agentCtx, { current: { provider: 'deepseek-official', model: 'deepseek-flash' }, assembled: undefined }); } });
  await inheritedHandle.agent.whenIdle();
  await boot.ctx.sessions.flush(inheritedHandle.agent.session);
  await boot.ctx.sessionPersistence.flush();
  proof.inheritedCapture = await capture(inheritedAgentId);
  const live = proof.inheritedCapture.liveHeader;
  const durable = proof.inheritedCapture.durableHeader;
  proof.conflictFixtures = {
    matchingRealInheritedHeaderAccepted: compareFixture(live, durable),
    inheritedDepthConflictRejected: !compareFixture({ ...live, delegationDepth: durable.delegationDepth + 1 }, durable),
    parentSessionConflictRejected: !compareFixture({ ...live, parentSession: randomUUID() }, durable),
    sessionIdConflictRejected: !compareFixture({ ...live, id: randomUUID() }, durable),
    cwdConflictRejected: !compareFixture({ ...live, cwd: root }, durable),
    createdAtConflictRejected: !compareFixture({ ...live, createdAt: live.createdAt + 1 }, durable),
    seededConflictRejected: !compareFixture({ ...live, isSeeded: !live.isSeeded }, durable),
    unexpectedFieldConflictRejected: !compareFixture({ ...live, unexpected: true }, durable),
  };
  proof.requestCount = requestCount;
  proof.rootModelAttempts = originalReconciliation.sessions[0]?.accounting?.attempts.length;
  proof.explicitRootModelAttempts = proof.explicitRootHelper.sessions[0]?.accounting?.attempts.length;
  proof.rootToolCalls = originalReconciliation.sessions[0]?.accounting?.toolCalls;
  proof.success = proof.rootCapture.rawHeaderEqual === false && proof.explicitRootCapture.rawHeaderEqual === true && originalReconciliation.sessions[0]?.blockers.includes('observation header differs from durable header') && proof.explicitRootHelper.blockers.length === 0 && proof.explicitRootHelper.sessions.every(session => session.blockers.length === 0) && Object.values(proof.conflictFixtures).every(Boolean) && requestCount === 0;
} catch (error) {
  proof.failure = { name: error.name, message: error.message, code: error.code ?? null };
  proof.success = false;
} finally {
  await inheritedHandle?.dispose();
  await handle?.dispose();
  await explicitHandle?.dispose();
  proof.requestCount = requestCount;
  await writeFile(join(root, 'proof.json'), JSON.stringify(proof, null, 2) + '\n', { mode: 0o600, flag: 'wx' });
  console.log(JSON.stringify({ proofPath: join(root, 'proof.json'), success: proof.success, requestCount, failure: proof.failure ?? null, rootCapture: proof.rootCapture, explicitRootCapture: proof.explicitRootCapture, inheritedCapture: proof.inheritedCapture, conflictFixtures: proof.conflictFixtures }, null, 2));
  await boot?.shutdown.shutdown(proof.success ? 0 : 2);
}
